using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class RecruitmentInterviewTests
{
 class Time:TimeProvider{public DateTimeOffset Now=new(2026,11,24,18,0,0,TimeSpan.Zero);public override DateTimeOffset GetUtcNow()=>Now;}
 class User(bool hr=true):ICurrentUser{public string Email=>"interview@example.local";public int? EmployeeId=>1;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>hr;public bool Can(string p)=>hr;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static RecruitmentInterviews S(AppDbContext d,Time? t=null,bool hr=true){var u=new User(hr);var c=new AppClock(t??new Time());return new(d,u,c,new AuditService(d,u,c));}
 static async Task<int> CandidateId(AppDbContext d)=>await d.Set<Candidate>().Where(x=>x.Stage!=CandidateStage.Hired&&x.Stage!=CandidateStage.Rejected).Select(x=>x.Id).FirstAsync();
 [Fact]public async Task ScheduleRecordsCairoTimeAndImmutableHistory(){await using var d=await Db();var id=await CandidateId(d);await S(d).ScheduleAsync(id,6,new(2026,12,1,10,0,0),60,"Fictional meeting room","Plan technical interview");var item=Assert.Single((await S(d).GetAsync()).Interviews);Assert.Equal(new DateTime(2026,12,1,8,0,0),item.StartsAt);Assert.Single((await S(d).GetAsync()).History);var ev=await d.Set<RecruitmentEvent>().FirstAsync();ev.Note="Tamper";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task CandidateAndInterviewerOverlapsRejectedButAdjacentAllowed(){await using var d=await Db();var id=await CandidateId(d);await S(d).ScheduleAsync(id,6,new(2026,12,1,10,0,0),60,"Room","Plan");await Assert.ThrowsAsync<DomainException>(()=>S(d).ScheduleAsync(id,7,new(2026,12,1,10,30,0),60,"Room","Candidate conflict"));var other=await d.Set<Candidate>().Where(x=>x.Id!=id&&x.Stage!=CandidateStage.Hired&&x.Stage!=CandidateStage.Rejected).Select(x=>x.Id).FirstAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d).ScheduleAsync(other,6,new(2026,12,1,10,30,0),60,"Room","Interviewer conflict"));await S(d).ScheduleAsync(other,6,new(2026,12,1,11,0,0),60,"Room","Adjacent");Assert.Equal(2,await d.Set<CandidateInterview>().CountAsync());}
 [Fact]public async Task CancellationAndCompletionRequireEvidenceAndNeverRepeat(){await using var d=await Db();var t=new Time();var id=await CandidateId(d);await S(d,t).ScheduleAsync(id,6,new(2026,12,1,10,0,0),60,"Room","Plan");var item=await d.Set<CandidateInterview>().FirstAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d,t).CloseAsync(item.Id,true,"Premature"));await Assert.ThrowsAsync<DomainException>(()=>S(d,t).CloseAsync(item.Id,false,""));await S(d,t).CloseAsync(item.Id,false,"Plan withdrawn");await Assert.ThrowsAsync<DomainException>(()=>S(d,t).CloseAsync(item.Id,false,"Again"));Assert.Equal(2,(await S(d).GetAsync()).History.Count);}
 [Fact]public async Task AuthorizationTerminalCandidatesAndInvalidInputsRejected(){await using var d=await Db();var id=await CandidateId(d);await Assert.ThrowsAsync<DomainException>(()=>S(d,hr:false).GetAsync());await Assert.ThrowsAsync<DomainException>(()=>S(d,hr:false).ScheduleAsync(id,6,new(2026,12,1,10,0,0),60,"Room","Plan"));await Assert.ThrowsAsync<DomainException>(()=>S(d).ScheduleAsync(id,6,new(2026,12,1,10,0,0),1,"Room","Plan"));var terminal=await d.Set<Candidate>().Where(x=>x.Stage==CandidateStage.Hired).FirstAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d).ScheduleAsync(terminal.Id,6,new(2026,12,1,10,0,0),60,"Room","Plan"));}
 [Fact]public async Task CompletedInterviewRequiresEndTimeAndRetainsOutcome(){await using var d=await Db();var t=new Time();var id=await CandidateId(d);await S(d,t).ScheduleAsync(id,6,new(2026,12,1,10,0,0),60,"Room","Plan");var item=await d.Set<CandidateInterview>().FirstAsync();t.Now=new(2026,12,1,8,30,0,TimeSpan.Zero);await Assert.ThrowsAsync<DomainException>(()=>S(d,t).CloseAsync(item.Id,true,"Too early"));t.Now=new(2026,12,1,9,0,0,TimeSpan.Zero);await S(d,t).CloseAsync(item.Id,true,"Fictional interview outcome");Assert.Equal("Completed",(await d.Set<CandidateInterview>().FindAsync(item.Id))!.Status);Assert.Contains((await S(d,t).GetAsync()).History,x=>x.Note=="Fictional interview outcome");}

}
